<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { apiGet, apiRequest } from '../services/api.js'
import { useAuthStore, roles, managementLevels } from '../stores/auth.js'
import { today, label } from '../utils.js'
import FormPanel from '../components/FormPanel.vue'
import SidePanel from '../components/SidePanel.vue'
import AppIcon from '../components/AppIcon.vue'
import { useWorkspaceStore } from '../stores/workspace.js'
import { formatDate, formatDateTime, normalizeSearch } from '../utils/workflow.js'
const auth = useAuthStore(), workspace = useWorkspaceStore(), route = useRoute(), router = useRouter()
const companies = computed(() => workspace.companies), company = computed({ get: () => workspace.companyId, set: value => { workspace.companyId = Number(value) } })
const data = ref(null), slots = ref([]), error = ref(''), notice = ref(''), invite = ref(''), busy = ref(false), section = ref(''), formKey = ref(0)
const activeTab = ref('people'), search = ref(''), statusFilter = ref('pending'), reviewing = ref(null), keepCreating = ref(false)
const pendingCount = computed(() => data.value?.beneficiaries.filter(b => b.status === 'pending').length || 0)
const beneficiaries = computed(() => (data.value?.beneficiaries || []).filter(b => (!statusFilter.value || b.status === statusFilter.value) && normalizeSearch(`${b.name} ${b.email || ''}`).includes(normalizeSearch(search.value))))
const titles = { company: 'Nova indústria', unit: 'Nova unidade industrial', contract: 'Contrato APS', invite: 'Convidar uma pessoa', minor: 'Cadastrar dependente menor', account: 'Novo profissional', team: 'Nova equipe', member: 'Vincular profissional', location: 'Local de atendimento', slot: 'Disponibilizar horário', assignment: 'Vínculo assistencial', review: 'Validar cadastro' }
function open(id, initial = {}) { section.value = id; formInitial.value = initial; contractEditing.value = null; formKey.value++; error.value = ''; invite.value = ''; keepCreating.value = false }
function close() { if (busy.value) return; section.value = ''; reviewing.value = null; if (route.query.new || route.query.review) router.replace({ path: route.path }) }
function review(b) { reviewing.value = b; open('review') }
function inviteFamily(b) { open('invite', { kind: 'dependent', sponsor_patient_id: Number(b.patient_id), contract_id: Number(b.contract_id), industry_unit_id: Number(b.industry_unit_id) }) }
function rowAction(b, event) {
  const action = event.target.value; event.target.value = ''
  if (action === 'family') inviteFamily(b)
  if (action === 'team') open('assignment', { patient_id: Number(b.patient_id) })
  if (action === 'suspend') validate(b, false)
}
const contractName = id => data.value?.contracts.find(c => Number(c.id) === Number(id))?.name || 'Contrato não identificado'
const unitName = id => data.value?.industry_units.find(u => Number(u.id) === Number(id))?.name || 'Unidade não identificada'
const workerOptions = computed(() => (data.value?.beneficiaries || []).filter(b => b.kind === 'worker' && b.status === 'active').map(b => ({ value: Number(b.patient_id), label: b.name, contract_id: Number(b.contract_id) })))
async function copyInvite() { try { await navigator.clipboard.writeText(invite.value); notice.value = 'Link copiado. Entregue somente ao destinatário.' } catch { notice.value = 'Selecione e copie o link abaixo.' } }
const platform = computed(() => auth.user.role === 'admin' && auth.user.management_level === 'platform')
const formInitial = ref({}), contractEditing = ref(null)
function editContract(c) { open('contract', { ...c, allow_in_person: !!Number(c.allow_in_person), allow_telehealth: !!Number(c.allow_telehealth), allow_dependents: !!Number(c.allow_dependents) }); contractEditing.value = c }
const careManagement = computed(() => platform.value || ['doctor', 'nurse'].includes(auth.user.role) && auth.user.management_level === 'coordination')
const entries = (rows, text = 'name') => (rows || []).map(r => ({ value: Number(r.id), label: r[text] }))
const field = (name, title, more = {}) => ({ name, label: title, ...more })
const sections = computed(() => [
  ...(platform.value ? [{ id: 'company', title: 'Nova indústria' }, { id: 'account', title: 'Usuários e níveis' }, { id: 'team', title: 'Criar equipe' }, { id: 'member', title: 'Vincular profissional' }] : []),
  { id: 'unit', title: 'Unidade industrial' }, { id: 'contract', title: 'Contrato APS' }, { id: 'invite', title: 'Convite de cadastro' }, { id: 'minor', title: 'Dependente menor' },
  ...(careManagement.value ? [{ id: 'location', title: 'Local de atendimento' }, { id: 'slot', title: 'Disponibilidade' }, { id: 'assignment', title: 'Vínculo assistencial' }] : []),
])
const forms = computed(() => {
  const coordinates = [field('latitude', 'Latitude', { type: 'number', optional: true, advanced: true }), field('longitude', 'Longitude', { type: 'number', optional: true, advanced: true })]
  const address = [field('name', 'Nome', { max: 150 }), field('address', 'Endereço', { max: 300 }), field('postal_code', 'CEP', { max: 9 }), ...coordinates]
  return {
    company: [field('name', 'Nome da indústria', { max: 150 })],
    unit: address,
    location: [...address, field('kind', 'Tipo de local', { options: [{ value: 'sesi', label: 'Unidade SESI' }, { value: 'industry', label: 'Na indústria' }] })],
    contract: [field('name', 'Identificação do contrato'), field('start_date', 'Início da vigência', { type: 'date', default: today() }), field('end_date', 'Fim da vigência', { type: 'date' }), field('status', 'Situação', { options: [{ value: 'active', label: 'Ativo' }, { value: 'paused', label: 'Pausado' }], default: 'active' }), field('allow_in_person', 'Inclui presencial', { type: 'checkbox', default: true }), field('allow_telehealth', 'Inclui teleconsulta', { type: 'checkbox', default: true }), field('allow_dependents', 'Inclui dependentes', { type: 'checkbox', default: true })],
    account: [field('name', 'Nome do profissional'), field('email', 'E-mail', { type: 'email' }), field('password', 'Senha inicial (12–72 bytes)', { type: 'password', max: 72 }), field('role', 'Perfil profissional', { options: ['doctor', 'nurse', 'navigator', 'manager'].map(value => ({ value, label: roles[value] })) }), field('management_level', 'Nível de gestão independente do perfil', { options: ['none', 'coordination', 'company'].map(value => ({ value, label: managementLevels[value] })), default: 'none', help: 'Coordenação: médico/enfermeiro. Gestão empresarial: gestor.' })],
    team: [field('name', 'Nome da equipe APS')],
    assignment: [field('patient_id', 'Beneficiário', { options: (data.value?.beneficiaries || []).map(b => ({ value: Number(b.patient_id), label: b.name })) }), field('team_id', 'Equipe APS', { options: entries(data.value?.teams) }), field('active', 'Vínculo ativo (desmarcar para revogar)', { type: 'checkbox', default: true }), field('authorization_verified', 'Verifiquei a autorização assistencial para esta equipe', { type: 'checkbox', wide: true })],
    member: [field('team_id', 'Equipe', { options: entries(data.value?.teams) }), field('user_id', 'Profissional', { options: entries(data.value?.professionals) })],
    invite: [field('kind', 'Quem será convidado?', { options: [{ value: 'worker', label: 'Trabalhador' }, { value: 'dependent', label: 'Dependente adulto' }], default: 'worker' }), field('email', 'E-mail da pessoa', { type: 'email' }), field('contract_id', 'Contrato vigente', { options: entries(data.value?.contracts.filter(c => c.status === 'active' && c.start_date <= today() && c.end_date >= today())) }), field('industry_unit_id', 'Unidade industrial', { options: entries(data.value?.industry_units) }), field('sponsor_patient_id', 'Trabalhador titular', { options: values => workerOptions.value.filter(w => !values.contract_id || w.contract_id === Number(values.contract_id)), when: values => values.kind === 'dependent' })],
    minor: [field('sponsor_patient_id', 'Trabalhador titular', { options: workerOptions.value }), field('name', 'Nome do dependente menor'), field('birth_date', 'Nascimento', { type: 'date' }), field('authorization_reference', 'Referência da verificação institucional da representação'), field('representation_verified', 'Verifiquei a representação e a autorização conforme o procedimento institucional', { type: 'checkbox', mustCheck: true, wide: true })],
    review: [field('contact_verified', 'Verifiquei o contato da pessoa', { type: 'checkbox', mustCheck: true }), field('affiliation_verified', 'Confirmei o vínculo e a cobertura do contrato', { type: 'checkbox', mustCheck: true })],
    slot: [field('professional_id', 'Profissional', { options: entries(data.value?.professionals.filter(p => ['doctor', 'nurse'].includes(p.role))) }), field('team_id', 'Equipe APS', { options: entries(data.value?.teams) }), field('service_unit_id', 'Local de atendimento', { options: entries(data.value?.service_units) }), field('modality', 'Modalidade', { options: [{ value: 'in_person', label: 'Presencial' }, { value: 'telehealth', label: 'Teleconsulta' }] }), field('starts_at', 'Início', { type: 'datetime-local' }), field('ends_at', 'Término', { type: 'datetime-local' })],
  }
})
const suffix = () => '?' + new URLSearchParams({ company_id: company.value })
async function load() { const [overview, agenda] = await Promise.all([apiGet('/management/overview' + suffix()), careManagement.value ? apiGet('/management/slots' + suffix()) : Promise.resolve([])]); data.value = overview; slots.value = agenda }
async function changeCompany() { section.value = ''; formInitial.value = {}; contractEditing.value = null; invite.value = ''; error.value = ''; notice.value = ''; data.value = null; busy.value = true; formKey.value++; try { await load(); statusFilter.value = pendingCount.value ? 'pending' : '' } catch (e) { error.value = e.message } finally { busy.value = false } }
async function submit(form) {
  busy.value = true; error.value = ''; notice.value = ''; invite.value = ''
  try {
    const endpoints = { company: 'companies', unit: 'industry-units', location: 'service-units', contract: 'contracts', account: 'users', team: 'teams', member: 'team-members', invite: 'invitations', minor: 'represented-dependents', slot: 'slots', assignment: 'care-assignments' }
    const payload = { ...form }
    for (const key of ['starts_at', 'ends_at']) if (payload[key]) payload[key] = payload[key].replace('T', ' ') + (payload[key].length === 16 ? ':00' : '')
    const editing = section.value === 'contract' && contractEditing.value
    const isReview = section.value === 'review'
    const endpoint = isReview ? `beneficiaries/${reviewing.value.id}` : endpoints[section.value] + (editing ? '/' + editing.id : '')
    const result = await apiRequest('/management/' + endpoint + suffix(), editing || isReview ? 'PUT' : 'POST', { ...payload, ...(isReview ? { status: 'active' } : {}), ...(editing ? { version: Number(editing.version) } : {}) })
    if (result.registration_path) invite.value = new URL(result.registration_path, window.location.origin).href
    if (section.value === 'company') { await workspace.ensure(auth.user, true); company.value = result.id }
    await load(); formKey.value++; contractEditing.value = null; notice.value = isReview ? 'Cadastro validado. A pessoa já pode buscar atendimento.' : 'Registro salvo com sucesso.'
    if (keepCreating.value && !isReview) { formInitial.value = ['slot', 'member', 'invite'].includes(section.value) ? Object.fromEntries(Object.entries(payload).filter(([k]) => ['team_id', 'professional_id', 'service_unit_id', 'modality', 'contract_id', 'industry_unit_id', 'kind'].includes(k))) : {} }
    else if (!result.registration_path) { section.value = ''; if (route.query.new || route.query.review) router.replace({ path: route.path }) }
  } catch (e) { error.value = e.message } finally { busy.value = false }
}
async function validate(b, activate) {
  if (activate) { review(b); return }
  busy.value = true; error.value = ''
  try { await apiRequest(`/management/beneficiaries/${b.id}` + suffix(), 'PUT', { status: activate ? 'active' : 'suspended', contact_verified: activate, affiliation_verified: activate }); await load() } catch (e) { error.value = e.message } finally { busy.value = false }
}
async function accountLevel(u, level) { busy.value = true; error.value = ''; try { await apiRequest(`/management/users/${u.id}` + suffix(), 'PUT', { management_level: level, active: !!Number(u.active) }); await load() } catch (e) { error.value = e.message } finally { busy.value = false } }
async function block(slot) { busy.value = true; error.value = ''; try { await apiRequest(`/management/slots/${slot.id}/block` + suffix(), 'POST', { version: Number(slot.version) }); await load() } catch (e) { error.value = e.message } finally { busy.value = false } }
function openFromRoute() {
  if (['people', 'structure', 'contracts', 'agenda', 'access'].includes(route.query.tab)) activeTab.value = route.query.tab
  const id = route.query.new
  if (sections.value.some(s => s.id === id)) open(id)
  const b = data.value?.beneficiaries.find(b => Number(b.id) === Number(route.query.review))
  if (b) review(b)
}
watch(() => route.query, () => { if (data.value) openFromRoute() })
onMounted(async () => { busy.value = true; try { await workspace.ensure(auth.user); await load(); statusFilter.value = pendingCount.value ? 'pending' : ''; openFromRoute() } catch (e) { error.value = e.message } finally { busy.value = false } })
</script>
<template>
  <div class="page-heading"><div><p class="eyebrow">GESTÃO PARA A INDÚSTRIA</p><h1>Pessoas e operação</h1><p class="text-secondary mb-0">Resolva pendências, convide pessoas e organize o atendimento.</p></div><button class="btn btn-success" :disabled="busy || !data" @click="open('invite')"><AppIcon name="plus" :size="18" /> Convidar pessoa</button></div>
  <div v-if="companies.length > 1" class="context-bar"><AppIcon name="building" /><label for="industry" class="visually-hidden">Indústria contratante</label><select id="industry" v-model="company" class="form-select" :disabled="busy" @change="changeCompany"><option v-for="c in companies" :key="c.id" :value="c.id">{{ c.name }}</option></select></div>
  <p v-else-if="companies.length" class="context-caption"><AppIcon name="building" :size="16" /> {{ companies[0].name }}</p>
  <p v-if="error && !section" class="alert alert-danger" role="alert">{{ error }}</p><p v-if="notice && !section" class="alert alert-success" role="status">{{ notice }}</p>
  <div v-if="!data && busy" class="loading-state" role="status"><span class="spinner-border spinner-border-sm" /> Preparando sua gestão…</div>
  <template v-if="data">
    <div class="task-strip"><button @click="activeTab = 'people'; statusFilter = 'pending'"><strong>{{ pendingCount }}</strong><span>cadastros para validar</span><AppIcon name="arrow" :size="16" /></button><button @click="activeTab = 'people'; statusFilter = ''"><strong>{{ data.beneficiaries.length }}</strong><span>trabalhadores e dependentes</span></button><button @click="activeTab = 'contracts'"><strong>{{ data.contracts.filter(c => c.status === 'active').length }}</strong><span>contratos ativos</span></button><button v-if="careManagement" @click="activeTab = 'agenda'"><strong>{{ slots.filter(s => s.status === 'available').length }}</strong><span>horários disponíveis</span></button></div>
    <div v-if="!data.industry_units.length || !data.contracts.length" class="setup-prompt"><AppIcon name="building" :size="28" /><div><strong>Vamos preparar esta indústria?</strong><p class="mb-0 small">Cadastre a unidade e o contrato para liberar os convites.</p></div><button class="btn btn-success ms-auto" @click="open(!data.industry_units.length ? 'unit' : 'contract')">{{ !data.industry_units.length ? 'Cadastrar unidade' : 'Cadastrar contrato' }} <AppIcon name="arrow" :size="16" /></button></div>
    <nav class="section-tabs" aria-label="Áreas de gestão"><button :class="{ active: activeTab === 'people' }" @click="activeTab = 'people'">Pessoas <span v-if="pendingCount" class="count-pill">{{ pendingCount }}</span></button><button :class="{ active: activeTab === 'structure' }" @click="activeTab = 'structure'">Unidades e equipes</button><button :class="{ active: activeTab === 'contracts' }" @click="activeTab = 'contracts'">Contratos</button><button v-if="careManagement" :class="{ active: activeTab === 'agenda' }" @click="activeTab = 'agenda'">Agenda</button><button v-if="platform" :class="{ active: activeTab === 'access' }" @click="activeTab = 'access'">Acessos</button></nav>
    <section v-if="activeTab === 'people'" class="card card-body">
      <div class="section-heading"><div><h2 class="h5 mb-1">Trabalhadores e dependentes</h2><p class="small text-secondary mb-0">Cadastro e elegibilidade. Informações clínicas ficam no acompanhamento assistencial.</p></div><button class="btn btn-sm btn-outline-success" @click="open('minor')">Cadastrar dependente menor</button></div>
      <div class="filter-toolbar"><div class="search-field"><AppIcon name="search" /><label for="people-search" class="visually-hidden">Buscar pessoa</label><input id="people-search" v-model="search" class="form-control" type="search" placeholder="Buscar por nome ou e-mail"></div><div class="filter-chips" aria-label="Situação do cadastro"><button v-for="s in [{ value: '', label: 'Todos' }, { value: 'pending', label: 'Para validar' }, { value: 'active', label: 'Ativos' }, { value: 'suspended', label: 'Suspensos' }]" :key="s.value" :class="{ active: statusFilter === s.value }" @click="statusFilter = s.value">{{ s.label }}</button></div></div>
      <div class="table-responsive"><table class="table align-middle"><thead><tr><th>Pessoa</th><th>Vínculo e unidade</th><th>Situação</th><th class="text-end">Próximo passo</th></tr></thead><tbody><tr v-for="b in beneficiaries" :key="b.id"><td><strong>{{ b.name }}</strong><small class="d-block text-secondary">{{ b.email || 'Cadastro com representação verificada' }}</small></td><td>{{ b.kind === 'worker' ? 'Trabalhador' : 'Dependente' }}<small class="d-block text-secondary">{{ unitName(b.industry_unit_id) }}</small></td><td><span class="status-badge" :class="b.status">{{ label(b.status) }}</span></td><td class="text-end"><button v-if="b.status !== 'active'" class="btn btn-sm btn-success" :disabled="busy" @click="review(b)">Validar cadastro</button><select v-else class="form-select row-action-select" :aria-label="`Ações para ${b.name}`" value="" :disabled="busy" @change="rowAction(b, $event)"><option value="" disabled>Ações</option><option v-if="b.kind === 'worker'" value="family">Convidar dependente</option><option v-if="careManagement" value="team">Vincular equipe APS</option><option value="suspend">Suspender elegibilidade</option></select></td></tr><tr v-if="!beneficiaries.length"><td colspan="4" class="empty-state">{{ statusFilter === 'pending' ? 'Nenhum cadastro aguardando validação. Tudo em dia!' : 'Nenhuma pessoa encontrada com esses filtros.' }}</td></tr></tbody></table></div>
    </section>
    <section v-if="activeTab === 'structure'" class="row g-4"><div class="col-lg-6"><div class="card card-body h-100"><div class="section-heading"><h2 class="h5">Unidades industriais</h2><button class="btn btn-sm btn-outline-success" @click="open('unit')">Adicionar</button></div><div v-for="u in data.industry_units" :key="u.id" class="list-entry"><AppIcon name="building" /><div><strong>{{ u.name }}</strong><small>{{ u.address }}</small></div></div><p v-if="!data.industry_units.length" class="empty-state">Comece pela unidade da indústria.</p><button v-if="platform" class="btn btn-link align-self-start mt-3" @click="open('company')">Cadastrar outra indústria</button></div></div><div class="col-lg-6"><div class="card card-body h-100"><div class="section-heading"><h2 class="h5">Equipes APS</h2><button v-if="platform" class="btn btn-sm btn-outline-success" @click="open('team')">Criar equipe</button></div><div v-for="t in data.teams" :key="t.id" class="list-entry"><AppIcon name="people" /><strong>{{ t.name }}</strong><button v-if="platform" class="btn btn-sm btn-link ms-auto" @click="open('member', { team_id: Number(t.id) })">Vincular profissional</button></div><div v-if="careManagement" class="mt-4"><div class="section-heading"><h3 class="h6">Locais de atendimento</h3><button class="btn btn-sm btn-outline-success" @click="open('location')">Adicionar local</button></div><p v-for="u in data.service_units" :key="u.id" class="small">{{ u.name }} · {{ u.address }}</p></div></div></div></section>
    <section v-if="activeTab === 'contracts'" class="card card-body"><div class="section-heading"><h2 class="h5">Contratos APS</h2><button class="btn btn-success" @click="open('contract')">Novo contrato</button></div><div v-for="c in data.contracts" :key="c.id" class="contract-row"><div><strong>{{ c.name }}</strong><p class="small text-secondary mb-2">{{ formatDate(c.start_date) }} a {{ formatDate(c.end_date) }}</p><div class="d-flex flex-wrap gap-2"><span class="status-badge" :class="c.status">{{ label(c.status) }}</span><span v-if="Number(c.allow_in_person)" class="soft-tag">Presencial</span><span v-if="Number(c.allow_telehealth)" class="soft-tag">Teleconsulta</span><span v-if="Number(c.allow_dependents)" class="soft-tag">Dependentes incluídos</span></div></div><button class="btn btn-sm btn-outline-success" @click="editContract(c)">Editar contrato</button></div><p v-if="!data.contracts.length" class="empty-state">Cadastre o contrato para definir a cobertura dos beneficiários.</p></section>
    <section v-if="activeTab === 'agenda' && careManagement" class="card card-body"><div class="section-heading"><div><h2 class="h5">Disponibilidade de atendimento</h2><p class="small text-secondary mb-0">Presencial e teleconsulta na mesma agenda.</p></div><button class="btn btn-success" @click="open('slot')">Disponibilizar horário</button></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Profissional e local</th><th>Horário</th><th>Modalidade</th><th>Situação</th><th></th></tr></thead><tbody><tr v-for="s in slots" :key="s.id"><td><strong>{{ s.professional_name }}</strong><small class="d-block text-secondary">{{ s.unit_name }}</small></td><td>{{ formatDateTime(s.starts_at) }}</td><td>{{ s.modality === 'telehealth' ? 'Teleconsulta' : 'Presencial' }}</td><td><span class="status-badge" :class="s.status">{{ label(s.status) }}</span></td><td><button v-if="s.status === 'available'" class="btn btn-sm btn-outline-secondary" :disabled="busy" @click="block(s)">Bloquear</button></td></tr><tr v-if="!slots.length"><td colspan="5" class="empty-state">Disponibilize o primeiro horário para iniciar os agendamentos.</td></tr></tbody></table></div></section>
    <section v-if="activeTab === 'access' && platform" class="card card-body"><div class="section-heading"><div><h2 class="h5">Profissionais e níveis de acesso</h2><p class="small text-secondary mb-0">O nível de gestão não concede acesso automático aos prontuários.</p></div><button class="btn btn-success" @click="open('account')">Novo profissional</button></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Profissional</th><th>Perfil</th><th>Nível de gestão</th></tr></thead><tbody><tr v-for="u in data.accounts" :key="u.id"><td><strong>{{ u.name }}</strong></td><td>{{ roles[u.role] }}</td><td><select v-if="['doctor', 'nurse', 'manager', 'navigator'].includes(u.role)" class="form-select" :aria-label="`Nível de ${u.name}`" :value="u.management_level" :disabled="busy" @change="accountLevel(u, $event.target.value)"><option value="none">Sem gestão</option><option v-if="['doctor', 'nurse'].includes(u.role)" value="coordination">Coordenação APS</option><option v-if="u.role === 'manager'" value="company">Gestão empresarial</option></select><span v-else>{{ managementLevels[u.management_level] }}</span></td></tr></tbody></table></div></section>
  </template>
  <SidePanel :open="!!section" :title="titles[section] || 'Cadastro'" :subtitle="reviewing && section === 'review' ? reviewing.name + ' · ' + contractName(reviewing.contract_id) : companies.find(c => Number(c.id) === Number(company))?.name" :busy="busy" @close="close">
    <p v-if="error" class="alert alert-danger" role="alert">{{ error }}</p>
    <div v-if="invite" class="invite-result"><span class="success-mark"><AppIcon name="check" :size="30" /></span><h3 class="h5">Convite pronto para compartilhar</h3><p class="text-secondary">Link individual válido por 48 horas. Entregue somente ao destinatário.</p><label for="invite-link" class="visually-hidden">Link de cadastro</label><input id="invite-link" class="form-control mb-3" :value="invite" readonly @focus="$event.target.select()"><button class="btn btn-success w-100" @click="copyInvite">Copiar link</button><p v-if="notice" class="small mt-3" role="status">{{ notice }}</p><button class="btn btn-link mt-3" @click="open('invite')">Convidar outra pessoa</button></div>
    <template v-else-if="section"><p v-if="section === 'review'" class="text-secondary mb-4">Confira o contato e a elegibilidade antes de liberar os agendamentos.</p><FormPanel :key="`${section}-${company}-${formKey}`" :fields="forms[section] || []" :initial="formInitial" :busy="busy" :submit-label="section === 'review' ? 'Validar e liberar agendamentos' : 'Salvar'" @submit="submit" /><label v-if="['slot', 'member', 'invite'].includes(section)" class="check-row mt-4"><input v-model="keepCreating" class="form-check-input" type="checkbox">Continuar cadastrando com os mesmos vínculos</label></template>
  </SidePanel>
</template>
